fun orderTasks(tasks: Set<String>, dependencies: List<Pair<String,String>>): List<String>? {val edges=tasks.associateWith{mutableSetOf<String>()};val degree=tasks.associateWith{0}.toMutableMap();for((t,p) in dependencies){if(t !in tasks||p !in tasks)return null;if(edges.getValue(p).add(t))degree[t]=degree.getValue(t)+1};val ready=java.util.PriorityQueue<String>();for(t in tasks)if(degree[t]==0)ready.add(t);val result=mutableListOf<String>();while(ready.isNotEmpty()){val t=ready.remove();result.add(t);for(n in edges.getValue(t)){degree[n]=degree.getValue(n)-1;if(degree[n]==0)ready.add(n)}};return if(result.size==tasks.size)result else null}
